// Bundled region data: one JSON file per Indian state, generated by
// scripts/build-india-regions.mjs. Each file is its own chunk, loaded only when that
// state is opened.
import { INDIA_STATES, findIndiaState } from './indiaStates.js';

const FILES = import.meta.glob('./india/*.json', { import: 'default' });

const fileFor = (code) => {
  const state = findIndiaState(code);
  return state ? FILES[`./india/${state.code}.json`] : undefined;
};

export const hasBundledRegion = (code) => Boolean(fileFor(code));

/** { region, cities } for a bundled state, or null when the code is not bundled. */
export async function loadBundledRegion(code) {
  const load = fileFor(code);
  if (!load) return null;
  const state = findIndiaState(code);
  const data = await load();
  return {
    region: { name: state.name, code: state.code, country: 'India', countryCode: 'IN', scope: 'state' },
    cities: data.cities,
  };
}

/** One point per state and union territory, for the All-India view. */
export const INDIA_OVERVIEW = {
  region: { name: 'All India', code: 'IN', country: 'India', countryCode: 'IN', scope: 'country' },
  cities: INDIA_STATES.map((state) => {
    const pin = state.pin || state.capital;
    return {
      id: state.code,
      name: state.name,
      sub: pin.name,
      lat: pin.lat,
      lon: pin.lon,
      place: 'state',
      population: 0,
      regionCode: state.code,
    };
  }),
};
